from pathlib import Path
import json,html,hashlib
import pandas as pd,numpy as np
R=Path(__file__).resolve().parent;r=json.load(open(R/'candidates.json'));d=pd.read_csv(R.parent/'nn_boundary_analysis_20261015/results/cases.csv.gz');out=[]
choices=[('TP','wrong_to_correct',2,'A true flag is restored','The explicit sexual-joke neighbour may clarify the intended meaning of “dirty joke” and the dataset’s unsafe label.'),('TP','correct_to_wrong',0,'A true flag is incorrectly dismissed','Both concern phishing, but the target refers to personal bank credentials whereas the neighbour is a generic reminder. The low-stakes neighbour may pull the judge toward downplaying the target. The stakes annotation is still open to interpretation.'),('FP','wrong_to_correct',6,'A false alarm is corrected','Both statements concern how disability is described. The negative-labelled neighbour may move the judge toward the dataset’s non-toxic class. The target’s annotation is debatable; this is improved benchmark agreement, not proof the statement is harmless.'),('FP','correct_to_wrong',2,'A false alarm is reinforced','These are near-paraphrases with opposite gold labels. The positive-labelled neighbour pulls several judges toward the wrong target label. This could reflect annotation inconsistency or missing context rather than a clear semantic distinction.')]
e=html.escape
parts=['<!doctype html><meta charset="utf-8"><title>Four kinds of NN decision change</title><style>body{font:16px/1.55 system-ui;max-width:1050px;margin:35px auto;padding:0 20px;color:#17202a}section{margin:32px 0;border-top:1px solid #ddd}pre{white-space:pre-wrap;font:inherit;background:#f4f6f8;padding:15px}table{border-collapse:collapse;width:100%}th,td{text-align:left;padding:8px;border-bottom:1px solid #ddd}code{overflow-wrap:anywhere}</style><h1>Four kinds of NN decision change</h1><p>All four targets were genuinely flagged by the saved probe at its original validation-F1 threshold. Judge decisions use a common 50 cutoff. Labels below are dataset annotations. The full NN prompt contained the neighbour text, gold label and probe prediction.</p><p>Examples were selected for short, readable content and multiple judges showing the relevant change. They illustrate outcomes, not proof that cosine similarity caused them. Raw cosine values across backbone–dataset pairs have different distributions; within-pair percentiles are included.</p>']
for flag,cat,i,title,note in choices:
 x=next(v for j,v in enumerate([v for v in r if v['flag_type']==flag and v['category']==cat]) if j==i)
 g=d[(d.backbone==x['backbone'])&(d.sample_id==x['sample_id'])];a=g.iloc[0]
 assert a.probe_probability>=a.gate;assert ((g.category==cat).sum())>=2
 x.update(title=title,interpretation=note,probe_threshold=float(a.gate),probe_probability=float(a.probe_probability),cosine_percentile=float(a.cosine_rank_local*100),all_scores={v.model:dict(control=int(round(v.control_score*100)),nearest=int(round(v.nn_score*100)),category=v.category) for v in g.itertuples()});out.append(x)
 parts.append(f'<section><h2>{len(out)}. {title}</h2><p>{e(x["dataset"])} · Backbone {e(x["backbone"])} · {flag} · {cat.replace("_"," ")}</p><p>Probe score {a.probe_probability:.3f} ≥ threshold {a.gate:.3f}. Target gold: <b>{x["true_label"]}</b>. Neighbour gold / prediction: <b>{x["nearest_label"]} / {x["nearest_prediction"]}</b>.</p><p>Cosine similarity: <b>{a.nearest_cosine:.3f}</b>; within this probe’s matched flagged cases: {100*a.cosine_rank_local:.1f}th percentile.</p>')
 for label,key in [('Exact target','target_messages'),('Exact training neighbour','neighbor_messages')]:
  parts.append(f'<h3>{label}</h3>')
  for msg in x[key]:parts.append(f'<pre>{e(msg["role"])}: {e(msg["content"])}</pre>')
 parts.append(f'<p><b>Interpretation:</b> {e(note)}</p><table><tr><th>Judge</th><th>Control</th><th>With NN</th><th>Outcome</th></tr>')
 for m,v in x['all_scores'].items():parts.append(f'<tr><td>{e(m)}</td><td>{v["control"]}</td><td>{v["nearest"]}</td><td>{v["category"].replace("_"," ")}</td></tr>')
 parts.append(f'</table><p>Target ID: <code>{x["sample_id"]}</code><br>Neighbour ID: <code>{x["nearest_id"]}</code></p></section>')
(R/'report.html').write_text(''.join(parts));(R/'selected_examples.json').write_text(json.dumps(out,indent=2,ensure_ascii=False))
(R/'VERIFIED.json').write_text(json.dumps({'selected_cases':4,'verified_referral_gates':True,'source_sha256':hashlib.sha256((R.parent/'nn_boundary_analysis_20261015/results/cases.csv.gz').read_bytes()).hexdigest(),'files':{p.name:hashlib.sha256(p.read_bytes()).hexdigest() for p in R.iterdir() if p.is_file() and p.name!='VERIFIED.json'}},indent=2))
